import Image from 'next/image';
import { BRAND_NAME } from '@dispatcher/shared';

// Generated by `npm run brand:assets` from packages/design-tokens/brand/.
// The web uses the dark theme only, so it always takes the on-dark variant.

/** Full logotype (symbol + wordmark) for login-style pages. */
export function BrandLogo({ width = 200, priority = false }: { width?: number; priority?: boolean }) {
  return (
    <Image
      src="/brand/logo-on-dark.png"
      alt={BRAND_NAME}
      width={width}
      height={Math.round((width * 506) / 960)}
      priority={priority}
      className="mx-auto"
    />
  );
}

/** Compact lockup for tight spaces (sidebar): symbol + name. */
export function BrandMark({ size = 32 }: { size?: number }) {
  return (
    <span className="flex items-center gap-2.5">
      <Image src="/brand/mark.png" alt="" width={size} height={size} />
      <span className="text-lg font-extrabold">{BRAND_NAME}</span>
    </span>
  );
}
